fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();

    // For length 0 or 1, return the input unchanged
    if n <= 1 {
        return numbers;
    }

    // Allocate output vector of the required size upfront
    let mut result = Vec::with_capacity(2 * n - 1);

    for i in 0..n {
        // Push the current element
        result.push(numbers[i]);

        // For all but the last element, add the delimiter
        if i < n - 1 {
            result.push(delimiter);
        }
    }

    result
}